import csv, json, os

INPUT_JSON = '/root/trivy_report.json'
OUTPUT_CSV = '/root/security_audit.csv'
FIELDNAMES = ['Package','Version','CVE_ID','Severity','CVSS_Score','Fixed_Version','Title','Url']

PREFERRED_SOURCES = ['nvd','ghsa','redhat']


def pick_cvss_score(cvss_obj):
    if not isinstance(cvss_obj, dict):
        return 'N/A'

    def numeric(x):
        return isinstance(x, (int, float))

    for src in PREFERRED_SOURCES:
        entry = cvss_obj.get(src)
        if not isinstance(entry, dict):
            continue
        for key in ('V3Score', 'V30Score', 'V2Score'):
            val = entry.get(key)
            if numeric(val):
                return str(val)
    # fallback: any source
    for entry in cvss_obj.values():
        if not isinstance(entry, dict):
            continue
        for key in ('V3Score', 'V30Score', 'V2Score'):
            val = entry.get(key)
            if numeric(val):
                return str(val)
    return 'N/A'


def pick_url(vuln):
    url = vuln.get('PrimaryURL')
    if isinstance(url, str) and url.strip():
        return url.strip()
    refs = vuln.get('References')
    if isinstance(refs, list) and refs:
        for r in refs:
            if isinstance(r, str) and r.strip():
                return r.strip()
    return 'N/A'


def pick_title(vuln):
    t = vuln.get('Title')
    d = vuln.get('Description')
    t = t.strip() if isinstance(t, str) else ''
    d = d.strip() if isinstance(d, str) else ''
    if t and d and d != t:
        return f'{t}: {d}'
    if t:
        return t
    if d:
        return d
    return 'N/A'


with open(INPUT_JSON, 'r', encoding='utf-8') as f:
    data = json.load(f)

rows_by_key = {}

total_vulns = 0
for res in (data.get('Results') or []):
    for v in (res.get('Vulnerabilities') or []):
        total_vulns += 1
        sev = (v.get('Severity') or '').upper()
        if sev not in {'HIGH', 'CRITICAL'}:
            continue

        pkg = v.get('PkgName') or 'N/A'
        ver = v.get('InstalledVersion') or 'N/A'
        cve = v.get('VulnerabilityID') or 'N/A'
        fixed = v.get('FixedVersion') or 'N/A'
        cvss = pick_cvss_score(v.get('CVSS'))
        url = pick_url(v)
        title = pick_title(v)

        row = {
            'Package': pkg,
            'Version': ver,
            'CVE_ID': cve,
            'Severity': sev,
            'CVSS_Score': cvss,
            'Fixed_Version': fixed,
            'Title': title,
            'Url': url,
        }

        key = (pkg, ver, cve)
        prev = rows_by_key.get(key)
        if prev is None:
            rows_by_key[key] = row
        else:
            # Prefer rows with a real CVSS score, then real URL
            def score_rank(r):
                return (r['CVSS_Score'] != 'N/A', r['Url'] != 'N/A')
            if score_rank(row) > score_rank(prev):
                rows_by_key[key] = row

rows = list(rows_by_key.values())
rows.sort(key=lambda r: (r['Severity'], r['Package'], r['CVE_ID'], r['Version']))

with open(OUTPUT_CSV, 'w', encoding='utf-8', newline='') as f:
    w = csv.DictWriter(f, fieldnames=FIELDNAMES)
    w.writeheader()
    for r in rows:
        w.writerow(r)

# Post-write validation
assert os.path.exists(OUTPUT_CSV), 'CSV was not created'
with open(OUTPUT_CSV, 'r', encoding='utf-8', newline='') as f:
    reader = csv.reader(f)
    header = next(reader)
    assert header == FIELDNAMES, f'Header mismatch: {header}'
    for i, rec in enumerate(reader, start=1):
        assert len(rec) == len(FIELDNAMES), f'Row {i} column mismatch'

with open(OUTPUT_CSV, 'r', encoding='utf-8', newline='') as f:
    dr = csv.DictReader(f)
    high = crit = 0
    for row in dr:
        assert row['Severity'] in {'HIGH', 'CRITICAL'}, f"Unexpected severity: {row['Severity']}"
        if row['Severity'] == 'HIGH':
            high += 1
        else:
            crit += 1

print('scan_total_vulns_in_json', total_vulns)
print('csv_rows_deduped', len(rows))
print('high_rows', high)
print('critical_rows', crit)
print('wrote', OUTPUT_CSV)
PY
